  function updateSaveState(){saveState.textContent=conflict?'Konflik penyimpanan':savePromise?'Menyimpan…':saveFailed?'Gagal menyimpan':dirty?'Belum tersimpan':'Tersimpan';saveState.classList.toggle('te-error',conflict||saveFailed);undo.disabled=busy||conflict||!history.past.length;redo.disabled=busy||conflict||!history.future.length;manualSave.disabled=busy||!ready;}
