  function addLayer(kind){if(!project||busy)return;if(kind==='subtitle'&&project.layers.some(l=>l.type==='subtitle')){selectLayer(project.layers.find(l=>l.type==='subtitle').id);notify('Satu layer subtitle sudah tersedia.');return;}change(p=>{const item=M.layer(kind,p.canvas);p.layers.push(item);selected=item.id;},true);}
  function showAudio(){tab='audio';selected=null;drawCanvas();drawLayers();drawProperties();}
