  function drawTiming(item){const section=node('section',undefined,'te-timing');section.append(node('h3','Waktu tampil'));if(item.type==='video'){section.append(node('p','Sumber video selalu mengikuti durasi highlight.','te-muted'));properties.append(section);return;}const timing=item.timing||{mode:'full',start:0,duration:4},mode=select([['full','Sepanjang clip'],['start','Dari awal'],['end','Menjelang akhir'],['percent','Persentase durasi']],timing.mode||'full');mode.onchange=()=>change(()=>{item.timing={...timing,mode:mode.value,start:0,duration:mode.value==='percent'?25:4};},true);field(section,'Aturan waktu',mode);if(timing.mode!=='full'){const percent=timing.mode==='percent';numberField(section,timing.mode==='end'?'Berakhir sebelum akhir (detik)':percent?'Mulai (%)':'Mulai (detik)',timing.start,value=>change(()=>item.timing.start=value),{min:0,max:percent?100:3600,step:percent?1:.1});numberField(section,percent?'Panjang (%)':'Lama tampil (detik)',timing.duration,value=>change(()=>item.timing.duration=value),{min:percent?1:.1,max:percent?100:3600,step:percent?1:.1});}properties.append(section);}
