  async function startRender(){await flush();const result=await call('editor_start_render',project.id,{});renderId=result.render.id;renderVersion=editVersion;renderRunning=true;resultPanel.hidden=false;renderedVideo.hidden=true;resultLink.hidden=true;renderStatus.textContent='Menyiapkan uji render…';progress.value=0;cancelRender.hidden=false;await pollRender();}
